__modules["core.db"] = function()
local ttt = require("ttt")
local U = require("core.util")
local S = require("core.state")
local R = require("core.results")
local Sqlite = require("core.sqlite")

-- An open database file: its attached databases (schemas), and per schema the
-- tables and views, loaded on demand. `version` goes up whenever a write may
-- have changed what is in it, so open views know to reload.
local M = {}

local function new_db(path)
  return {
    path = path,
    name = U.basename(path),
    attachments = S.attachments(path),
    schemas = { "main", "temp" },
    files = {},
    schema = "main",
    objects = {},
    info = nil,
    status = "idle",
    err = nil,
    version = 0,
    gen = 0,
  }
end

function M.get(path)
  local db = S.dbs[path]
  if not db then
    db = new_db(path)
    S.dbs[path] = db
  end
  return db
end

function M.open(path)
  local db = M.get(path)
  S.current = db
  S.remember(path)
  if db.status == "idle" or db.status == "error" then
    M.load(db)
  end
  S.redraw()
  return db
end

function M.close(db)
  if S.current == db then
    S.current = nil
  end
  S.dbs[db.path] = nil
  S.redraw()
end

function M.schema_state(db, schema)
  local st = db.objects[schema]
  if not st then
    st = { tables = {}, views = {}, counts = {}, loading = false, loaded = false, err = nil, gen = 0 }
    db.objects[schema] = st
  end
  return st
end

local INFO_SQL = [[
SELECT 'schema' AS k, name, file FROM pragma_database_list ORDER BY seq;
SELECT 'info' AS k, sqlite_version() AS version,
  (SELECT encoding FROM pragma_encoding) AS encoding,
  (SELECT journal_mode FROM pragma_journal_mode) AS journal_mode,
  (SELECT page_size FROM pragma_page_size) AS page_size,
  (SELECT user_version FROM pragma_user_version) AS user_version;]]

local function info_loaded(db, gen, err, sets)
  if gen ~= db.gen then
    return
  end
  local t = R.tagged(sets)
  if not t.info then
    db.status = "error"
    db.err = err or "Could not read the database"
    S.redraw()
    return
  end
  db.status = "ok"
  db.err = err
  db.info = t.info[1]
  local schemas, files = { "main", "temp" }, { main = db.path }
  for _, rec in ipairs(t.schema or {}) do
    if rec.name ~= "main" and rec.name ~= "temp" then
      schemas[#schemas + 1] = rec.name
    end
    files[rec.name] = rec.file
  end
  for _, a in ipairs(db.attachments) do
    if not files[a.alias] then
      schemas[#schemas + 1] = a.alias
    end
  end
  db.schemas = schemas
  db.files = files
  local valid = false
  for _, s in ipairs(schemas) do
    valid = valid or s == db.schema
  end
  if not valid then
    db.schema = "main"
  end
  M.load_objects(db, db.schema)
  S.redraw()
end

-- Reloads what the database holds: its schemas, then the selected schema's
-- tables and views.
function M.load(db)
  db.gen = db.gen + 1
  db.status = "loading"
  db.objects = {}
  Sqlite.run(db, INFO_SQL, {}, U.bind(info_loaded, db, db.gen))
end

local function size_sql(schema)
  local lit = U.literal(schema)
  return "SELECT 'size' AS k, (SELECT page_count FROM pragma_page_count("
    .. lit
    .. ")) * (SELECT page_size FROM pragma_page_size("
    .. lit
    .. ")) AS bytes;"
end

local function objects_sql(schema)
  return "SELECT 'obj' AS k, name, type, sql FROM "
    .. U.ident(schema)
    .. ".sqlite_master WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite!_%' ESCAPE '!' ORDER BY name;\n"
    .. size_sql(schema)
end

local function counts_loaded(db, st, gen, _, sets)
  if gen ~= st.gen then
    return
  end
  for _, rec in ipairs(R.tagged(sets).count or {}) do
    st.counts[rec.name] = tonumber(rec.n)
  end
  st.counting = false
  S.redraw()
end

local function count_tables(db, schema, st)
  local parts = {}
  for _, t in ipairs(st.tables) do
    if not t.virtual then
      parts[#parts + 1] = "SELECT 'count' AS k, "
        .. U.literal(t.name)
        .. " AS name, count(*) AS n FROM "
        .. U.qualified(schema, t.name)
        .. ";"
    end
  end
  if #parts == 0 then
    return
  end
  st.counting = true
  Sqlite.run(db, table.concat(parts, "\n"), { bail = false }, U.bind(counts_loaded, db, st, st.gen))
end

local function objects_loaded(db, schema, st, gen, err, sets)
  if gen ~= st.gen then
    return
  end
  st.loading = false
  st.loaded = true
  local t = R.tagged(sets)
  if err and not t.obj then
    st.err = err
  end
  st.tables, st.views = {}, {}
  for _, rec in ipairs(t.obj or {}) do
    local item = { name = rec.name, type = rec.type, sql = rec.sql }
    if rec.type == "view" then
      st.views[#st.views + 1] = item
    else
      item.virtual = (rec.sql or ""):upper():find("^%s*CREATE%s+VIRTUAL") ~= nil
      st.tables[#st.tables + 1] = item
    end
  end
  st.bytes = t.size and tonumber(t.size[1].bytes)
  if st.bytes and st.bytes <= (tonumber(S.settings.count_limit_mib) or 0) * 1024 * 1024 then
    count_tables(db, schema, st)
  end
  S.redraw()
end

function M.load_objects(db, schema)
  local st = M.schema_state(db, schema)
  st.gen = st.gen + 1
  st.loading = true
  st.err = nil
  st.counts = {}
  Sqlite.run(db, objects_sql(schema), {}, U.bind(objects_loaded, db, schema, st, st.gen))
  return st
end

function M.ensure_objects(db, schema)
  local st = M.schema_state(db, schema)
  if not st.loaded and not st.loading and db.status == "ok" then
    M.load_objects(db, schema)
  end
  return st
end

function M.select_schema(db, schema)
  db.schema = schema
  M.ensure_objects(db, schema)
  S.redraw()
end

-- After a query that may have written: reload everything that is cached.
function M.changed(db)
  db.version = db.version + 1
  M.load(db)
end

function M.find(db, schema, name)
  local st = db.objects[schema]
  if not st then
    return nil
  end
  for _, list in ipairs({ st.tables, st.views }) do
    for _, item in ipairs(list) do
      if item.name == name then
        return item
      end
    end
  end
end

function M.attach(db, path, alias)
  for _, a in ipairs(db.attachments) do
    if a.alias:lower() == alias:lower() then
      return "A database is already attached as " .. alias
    end
  end
  table.insert(db.attachments, { path = path, alias = alias })
  S.save_attachments(db.path, db.attachments)
  db.schema = alias
  M.load(db)
  ttt.notify("Attached " .. U.basename(path) .. " as " .. alias)
end

function M.detach(db, alias)
  local list = {}
  for _, a in ipairs(db.attachments) do
    if a.alias ~= alias then
      list[#list + 1] = a
    end
  end
  db.attachments = list
  S.save_attachments(db.path, list)
  if db.schema == alias then
    db.schema = "main"
  end
  M.load(db)
  ttt.notify("Detached " .. alias)
end

function M.is_attached(db, schema)
  for _, a in ipairs(db.attachments) do
    if a.alias == schema then
      return true
    end
  end
  return false
end

return M
end

-- src/core/results.lua ------------------------------------------------------
__modules["core.results"] = function()
-- Parses what `sqlite3 -json` prints: one JSON array of flat objects per
-- statement that returned rows, one after another. ttt.json would lose the
-- column order and duplicate column names, and turn large integers into
-- floats, so this reads the objects itself and keeps every value as text.
local M = {}

local function null_text()
  return "NULL"
end

M.NULL = setmetatable({}, { __tostring = null_text })

local function utf8(cp)
  if cp < 0x80 then
    return string.char(cp)
  elseif cp < 0x800 then
    return string.char(0xC0 + math.floor(cp / 0x40), 0x80 + cp % 0x40)
  elseif cp < 0x10000 then
    return string.char(0xE0 + math.floor(cp / 0x1000), 0x80 + math.floor(cp / 0x40) % 0x40, 0x80 + cp % 0x40)
  end
  return string.char(
    0xF0 + math.floor(cp / 0x40000),
    0x80 + math.floor(cp / 0x1000) % 0x40,
    0x80 + math.floor(cp / 0x40) % 0x40,
    0x80 + cp % 0x40
  )
end

local ESCAPES = { b = "\b", f = "\f", n = "\n", r = "\r", t = "\t" }

local function fail(i, what)
  error({ parse = true, message = "unexpected sqlite3 output at byte " .. i .. ": " .. what }, 0)
end

local function skip(s, i)
  local _, e = s:find("^[ \t\r\n,]*", i)
  return e + 1
end

local function read_string(s, i)
  local parts = {}
  local start = i + 1
  while true do
    local j = s:find('["\\]', start)
    if not j then
      fail(i, "unterminated string")
    end
    parts[#parts + 1] = s:sub(start, j - 1)
    if s:byte(j) == 34 then
      return table.concat(parts), j + 1
    end
    local c = s:sub(j + 1, j + 1)
    if c == "u" then
      local cp = tonumber(s:sub(j + 2, j + 5), 16) or 63
      local nexti = j + 6
      if cp >= 0xD800 and cp <= 0xDBFF and s:sub(nexti, nexti + 1) == "\\u" then
        local lo = tonumber(s:sub(nexti + 2, nexti + 5), 16)
        if lo and lo >= 0xDC00 and lo <= 0xDFFF then
          cp = 0x10000 + (cp - 0xD800) * 0x400 + (lo - 0xDC00)
          nexti = nexti + 6
        end
      end
      parts[#parts + 1] = utf8(cp)
      start = nexti
    else
      parts[#parts + 1] = ESCAPES[c] or c
      start = j + 2
    end
  end
end

-- Returns the value as text (or NULL), whether it was a number, and the next
-- position.
local function read_value(s, i)
  local b = s:byte(i)
  if b == 34 then
    local v, nexti = read_string(s, i)
    return v, false, nexti
  end
  if s:sub(i, i + 3) == "null" then
    return M.NULL, false, i + 4
  end
  local _, e = s:find("^[%w%.%+%-]+", i)
  if not e then
    fail(i, "expected a value")
  end
  return s:sub(i, e), true, e + 1
end

local function read_object(s, i, set)
  local row, col = {}, 0
  i = skip(s, i + 1)
  while s:byte(i) ~= 125 do
    if s:byte(i) ~= 34 then
      fail(i, "expected a column name")
    end
    local name, nexti = read_string(s, i)
    i = skip(s, nexti)
    if s:byte(i) ~= 58 then
      fail(i, "expected ':'")
    end
    i = skip(s, i + 1)
    local value, numeric
    value, numeric, i = read_value(s, i)
    col = col + 1
    if not set.columns[col] then
      set.columns[col] = name
      set.numeric[col] = true
    end
    if value ~= M.NULL and not numeric then
      set.numeric[col] = false
    end
    row[col] = value
    i = skip(s, i)
  end
  return row, i + 1
end

local function read_array(s, i, limit)
  local set = { columns = {}, numeric = {}, rows = {}, truncated = false }
  i = skip(s, i + 1)
  while s:byte(i) == 123 do
    local row
    row, i = read_object(s, i, set)
    if #set.rows < limit then
      set.rows[#set.rows + 1] = row
    else
      set.truncated = true
    end
    i = skip(s, i)
  end
  if s:byte(i) ~= 93 then
    fail(i, "expected ']'")
  end
  return set, i + 1
end

local function parse(s, limit)
  local sets, notes = {}, {}
  local i = 1
  local n = #s
  while true do
    local _, e = s:find("^%s*", i)
    i = e + 1
    if i > n then
      break
    end
    if s:byte(i) == 91 then
      local set
      set, i = read_array(s, i, limit)
      sets[#sets + 1] = set
    else
      local j = s:find("\n", i, true) or n + 1
      notes[#notes + 1] = s:sub(i, j - 1)
      i = j + 1
    end
  end
  return sets, notes
end

-- Returns sets, notes (lines that were not JSON, from dot-commands), or nil
-- and an error. Each set is { columns, numeric, rows, truncated }; a row is an
-- array of strings and NULL. Rows past limit are counted out as truncated.
function M.parse(s, limit)
  local ok, sets, notes = pcall(parse, s or "", limit or math.huge)
  if not ok then
    if type(sets) == "table" and sets.parse then
      return nil, sets.message
    end
    return nil, tostring(sets)
  end
  return sets, notes
end

-- Rows as tables keyed by column name, for queries the plugin writes itself.
function M.records(set)
  local out = {}
  for r, row in ipairs(set and set.rows or {}) do
    local rec = {}
    for c, name in ipairs(set.columns) do
      local v = row[c]
      if v ~= M.NULL then
        rec[name] = v
      end
    end
    out[r] = rec
  end
  return out
end

-- The records of every set, grouped by their first column, which the
-- plugin's own queries use as a tag: sqlite3 prints nothing for a statement
-- without rows, so position alone cannot say which set is which.
function M.tagged(sets)
  local out = {}
  for _, set in ipairs(sets or {}) do
    for _, rec in ipairs(M.records(set)) do
      local tag = rec[set.columns[1]]
      if tag then
        out[tag] = out[tag] or {}
        table.insert(out[tag], rec)
      end
    end
  end
  return out
end

function M.text(v)
  if v == nil or v == M.NULL then
    return "NULL"
  end
  return v
end

return M
end

-- src/core/sqlite.lua -------------------------------------------------------
__modules["core.sqlite"] = function()
local sys = require("ttt.system")
local U = require("core.util")
local S = require("core.state")
local R = require("core.results")

-- Every call runs one sqlite3 process: `sqlite3 -json <uri>` with the SQL on
-- stdin. Attached databases are attached again each time with -cmd.
local M = {}

local noinit = true

local function attach_args(db, write)
  local args = {}
  for _, a in ipairs(db.attachments or {}) do
    args[#args + 1] = "-cmd"
    args[#args + 1] = "ATTACH " .. U.literal(U.uri(a.path, write)) .. " AS " .. U.ident(a.alias)
  end
  return args
end

local function build_args(db, opts)
  local args = {}
  if noinit then
    args[#args + 1] = "-noinit"
  end
  args[#args + 1] = "-batch"
  args[#args + 1] = "-json"
  for _, a in ipairs(attach_args(db, opts.write)) do
    args[#args + 1] = a
  end
  -- -bail on the command line makes sqlite3 exit right after the first -cmd
  -- SQL, before reading stdin; turning it on from a -cmd after ATTACH works.
  if opts.bail ~= false then
    args[#args + 1] = "-cmd"
    args[#args + 1] = ".bail on"
  end
  args[#args + 1] = U.uri(db.path, opts.write)
  return args
end

local function friendly(err)
  err = U.trim(err)
  if err:find("executable file not found", 1, true) or err:find("no such file or directory", 1, true) then
    return "sqlite3 not found: " .. S.binary() .. " (see SQLite: Settings…)"
  end
  if err:find("permission denied: system.exec", 1, true) then
    return "Not in system.exec in plugin.ttt.json: " .. S.binary()
  end
  return err
end

local function finished(db, sql, opts, cb, started, result)
  local stderr = result.stderr or ""
  if noinit and stderr:find("-noinit", 1, true) and stderr:find("unknown option", 1, true) then
    noinit = false
    return M.run(db, sql, opts, cb)
  end
  local elapsed = os.clock() - started
  if result.exit_code == -1 then
    return cb(friendly(stderr), {}, { elapsed = elapsed })
  end
  local sets, notes = R.parse(result.stdout, opts.limit)
  if not sets then
    return cb(notes, {}, { elapsed = elapsed })
  end
  local err = U.trim(stderr)
  if err == "" and result.exit_code ~= 0 then
    err = "sqlite3 exited with code " .. tostring(result.exit_code)
  end
  cb(err ~= "" and err or nil, sets, { elapsed = elapsed, notes = notes, exit_code = result.exit_code })
end

-- cb(err, sets, info): err is sqlite3's stderr when it printed anything; the
-- sets that ran before an error are still passed. opts: write (open
-- read-write), bail (stop at the first error, default true), limit (rows kept
-- per set).
function M.run(db, sql, opts, cb)
  opts = opts or {}
  if not sys.exec_async then
    return cb("This plugin needs the system.exec permission to run sqlite3", {}, {})
  end
  local started = os.clock()
  local _, err = sys.exec_async(
    S.binary(),
    build_args(db, opts),
    { stdin = sql .. "\n" },
    U.bind(finished, db, sql, opts, cb, started)
  )
  if err then
    cb(friendly(err), {}, {})
  end
end

local function version_done(cb, result)
  local out = U.trim(result.stdout)
  if result.exit_code ~= 0 or out == "" then
    return cb(friendly(result.stderr ~= "" and result.stderr or "sqlite3 -version failed"))
  end
  cb(nil, out:match("^(%S+)") or out)
end

function M.version(cb)
  if not sys.exec_async then
    return cb("This plugin needs the system.exec permission to run sqlite3")
  end
  local _, err = sys.exec_async(S.binary(), { "-version" }, U.bind(version_done, cb))
  if err then
    cb(friendly(err))
  end
end

return M
end

