__modules["features.table.data"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Store = require("features.table.store")

local M = {}

local function set_draft(tv, text)
  tv.data.draft = text
end

local function order_options(tv)
  local options = { { label = "Default order", value = "" } }
  for _, c in ipairs(tv.structure.columns or {}) do
    if tonumber(c.hidden) ~= 1 then
      options[#options + 1] = { label = "Order by " .. c.name, value = c.name }
    end
  end
  return options
end

local function filter_input(p, tv)
  p:input({
    border = true,
    margin_top = 1,
    title = "Filter",
    prefix = "WHERE ",
    placeholder = "SQL condition, Enter to apply",
    value = tv.data.draft,
    on_change = U.bind(set_draft, tv),
    on_submit = U.bind(Store.apply_filter, tv),
  })
end

local function order_row(tv, h)
  UI.dropdown(h, order_options(tv), tv.data.order, U.bind(Store.set_order, tv))
  h:button({
    label = tv.data.desc and "↓ Descending" or "↑ Ascending",
    style = "bracket",
    disabled = tv.data.order == "",
    on_click = U.bind(Store.toggle_desc, tv),
  })
end

local function column_names(tv)
  local names, numeric = {}, {}
  for _, c in ipairs(tv.structure.columns or {}) do
    if tonumber(c.hidden) ~= 1 then
      names[#names + 1] = c.name
    end
  end
  return names, numeric
end

local function status_text(tv)
  local d = tv.data
  if d.loading then
    return "Loading…", "muted"
  end
  if d.err then
    return "✕ " .. U.one_line(d.err), "danger"
  end
  local text = U.plural(d.total, "row")
  if d.filter ~= "" then
    text = text .. " match the filter"
  end
  return text, "muted"
end

local function grid_box(tv, width, b)
  local d = tv.data
  local set = d.set or {}
  local columns, numeric = set.columns, set.numeric
  if not columns or #columns == 0 then
    columns, numeric = column_names(tv)
  end
  UI.grid(b, tv.grid, {
    columns = columns,
    numeric = numeric,
    rows = set.rows or {},
    width = width - 2,
    offset = d.offset,
    limit = S.page_size(),
    total = d.total,
    on_page = U.bind(Store.set_page, tv),
    loading = d.loading,
    empty = d.err and "Couldn't load rows" or (d.filter ~= "" and "No rows match the filter" or "No rows"),
    row_title = tv.name,
  })
end

local function status_row(tv, h)
  local text, style = status_text(tv)
  h:label({ text = text, style = style, padding_left = 1 })
  order_row(tv, h)
end

function M.render(p, tv)
  Store.ensure_structure(tv)
  Store.ensure_data(tv)
  local width = p:size()
  filter_input(p, tv)
  p:hstack({ height = 1, gap = 1, render = U.bind(status_row, tv) })
  if tv.structure.err then
    p:label({ text = "! " .. U.one_line(tv.structure.err), style = "warning", padding_left = 1 })
  end
  UI.frame(p, "Rows", U.bind(grid_box, tv, width))
end

return M
end

-- src/features/table/init.lua -----------------------------------------------
__modules["features.table"] = function()
local U = require("core.util")
local Router = require("app.router")
local Store = require("features.table.store")
local Data = require("features.table.data")
local Structure = require("features.table.structure")
local Query = require("features.query")

local M = {}

local TABS = { { id = "data", label = "Data" }, { id = "structure", label = "Structure" } }

local function new_query(tv)
  Query.open(tv.db, "SELECT * FROM " .. U.qualified(tv.schema, tv.name) .. " LIMIT 100;")
end

local function actions(tv, h)
  h:button({ label = "Query", on_click = U.bind(new_query, tv) })
  h:button({ label = "Refresh", on_click = U.bind(Store.refresh, tv) })
end

local function render(page, tv, p)
  Store.check_version(tv)
  if Router.tab_strip(p, page, TABS) == "structure" then
    Structure.render(p, tv)
  else
    Data.render(p, tv)
  end
end

local function make_page(db, schema, name, kind)
  local tv = Store.new_view(db, schema, name, kind)
  local page = {
    title = name,
    trail = { db.name, schema },
    tab_title = schema == "main" and name or (schema .. "." .. name),
    db_path = db.path,
  }
  page.render = U.bind(render, page, tv)
  page.actions = U.bind(actions, tv)
  return page
end

function M.open(db, schema, name, kind)
  return Router.show("table:" .. db.path .. "::" .. schema .. "::" .. name, U.bind(make_page, db, schema, name, kind))
end

return M
end

-- src/features/table/store.lua ----------------------------------------------
__modules["features.table.store"] = function()
local U = require("core.util")
local S = require("core.state")
local R = require("core.results")
local Sqlite = require("core.sqlite")
local UI = require("components")

-- One table or view's state: its structure, and the page of rows on show.
local M = {}

function M.new_view(db, schema, name, kind)
  return {
    db = db,
    schema = schema,
    name = name,
    kind = kind,
    version = db.version,
    structure = { loaded = false, loading = false, gen = 0 },
    data = {
      loaded = false,
      loading = false,
      gen = 0,
      offset = 0,
      total = 0,
      filter = "",
      draft = "",
      order = "",
      desc = false,
      counted = nil,
    },
    grid = UI.new_grid(),
  }
end

local function structure_sql(tv)
  local name, schema = U.literal(tv.name), U.literal(tv.schema)
  local master = U.ident(tv.schema) .. ".sqlite_master"
  return table.concat({
    "SELECT 'col' AS k, cid, name, type, \"notnull\" AS not_null, dflt_value, pk, hidden FROM pragma_table_xinfo("
      .. name
      .. ", "
      .. schema
      .. ") ORDER BY cid;",
    "SELECT 'idx' AS k, il.seq AS seq, il.name AS name, il.\"unique\" AS uniq, il.origin AS origin, il.partial AS partial,"
      .. " (SELECT group_concat(coalesce(ii.name, '<expr>'), ', ') FROM pragma_index_xinfo(il.name, "
      .. schema
      .. ") ii WHERE ii.key) AS cols,"
      .. " (SELECT m.sql FROM "
      .. master
      .. " m WHERE m.type = 'index' AND m.name = il.name) AS sql"
      .. " FROM pragma_index_list("
      .. name
      .. ", "
      .. schema
      .. ") il ORDER BY il.name;",
    'SELECT \'fk\' AS k, id, seq, "table" AS ref, "from" AS src, "to" AS dst, on_update, on_delete FROM pragma_foreign_key_list('
      .. name
      .. ", "
      .. schema
      .. ") ORDER BY id, seq;",
    "SELECT 'sql' AS k, type, sql FROM " .. master .. " WHERE name = " .. name .. " AND type IN ('table', 'view');",
    "SELECT 'trg' AS k, name, sql FROM "
      .. master
      .. " WHERE type = 'trigger' AND tbl_name = "
      .. name
      .. " ORDER BY name;",
  }, "\n")
end

local function group_fks(rows)
  local fks, by_id = {}, {}
  for _, r in ipairs(rows or {}) do
    local fk = by_id[r.id]
    if not fk then
      fk = { ref = r.ref, src = {}, dst = {}, on_update = r.on_update, on_delete = r.on_delete }
      by_id[r.id] = fk
      fks[#fks + 1] = fk
    end
    fk.src[#fk.src + 1] = r.src or ""
    if r.dst then
      fk.dst[#fk.dst + 1] = r.dst
    end
  end
  return fks
end

local function structure_loaded(tv, gen, err, sets)
  local st = tv.structure
  if gen ~= st.gen then
    return
  end
  local t = R.tagged(sets)
  st.loading = false
  st.loaded = true
  st.err = err
  st.columns = t.col or {}
  st.indexes = t.idx or {}
  st.fks = group_fks(t.fk)
  st.sql = t.sql and t.sql[1] and t.sql[1].sql or ""
  st.triggers = t.trg or {}
  S.redraw()
  M.ensure_data(tv)
end

function M.load_structure(tv)
  local st = tv.structure
  st.gen = st.gen + 1
  st.loading = true
  Sqlite.run(tv.db, structure_sql(tv), {}, U.bind(structure_loaded, tv, st.gen))
end

function M.ensure_structure(tv)
  if not tv.structure.loaded and not tv.structure.loading then
    M.load_structure(tv)
  end
end

-- Blobs show as their size: sqlite3 -json prints their bytes as text.
local function select_list(tv)
  local cols = {}
  for _, c in ipairs(tv.structure.columns or {}) do
    if tonumber(c.hidden) ~= 1 then
      local q = U.ident(c.name)
      cols[#cols + 1] = "CASE WHEN typeof("
        .. q
        .. ") = 'blob' THEN printf('<blob %d bytes>', length("
        .. q
        .. ")) ELSE "
        .. q
        .. " END AS "
        .. q
    end
  end
  if #cols == 0 then
    return "*"
  end
  return table.concat(cols, ", ")
end

local function where(d)
  local f = U.trim(d.filter)
  if f == "" then
    return ""
  end
  return " WHERE " .. f
end

local function data_sql(tv, with_count)
  local d = tv.data
  local from = " FROM " .. U.qualified(tv.schema, tv.name) .. where(d)
  local parts = {}
  if with_count then
    parts[#parts + 1] = "SELECT count(*) AS n" .. from .. ";"
  end
  local order = ""
  if d.order ~= "" then
    order = " ORDER BY " .. U.ident(d.order) .. (d.desc and " DESC" or " ASC")
  end
  parts[#parts + 1] = "SELECT "
    .. select_list(tv)
    .. from
    .. order
    .. " LIMIT "
    .. S.page_size()
    .. " OFFSET "
    .. d.offset
    .. ";"
  return table.concat(parts, "\n")
end

local function data_loaded(tv, gen, with_count, err, sets)
  local d = tv.data
  if gen ~= d.gen then
    return
  end
  d.loading = false
  d.loaded = true
  d.err = err
  local rows_set = sets[1]
  if with_count then
    if sets[1] and not err then
      d.total = tonumber(sets[1].rows[1] and sets[1].rows[1][1]) or 0
      d.counted = d.filter
    end
    rows_set = sets[2]
  end
  if rows_set then
    d.set = rows_set
  else
    d.set = { columns = d.set and d.set.columns or {}, numeric = {}, rows = {} }
  end
  if err then
    d.set.rows = {}
  end
  S.redraw()
end

function M.load_data(tv, recount)
  local d = tv.data
  local with_count = recount or d.counted ~= d.filter
  d.gen = d.gen + 1
  d.loading = true
  Sqlite.run(tv.db, data_sql(tv, with_count), {}, U.bind(data_loaded, tv, d.gen, with_count))
end

function M.ensure_data(tv)
  if tv.structure.loaded and not tv.data.loaded and not tv.data.loading then
    M.load_data(tv)
  end
end

-- Reloads when a query changed the database since this view last loaded.
function M.check_version(tv)
  if tv.version ~= tv.db.version then
    tv.version = tv.db.version
    M.refresh(tv)
  end
end

function M.refresh(tv)
  tv.data.loaded = false
  tv.data.counted = nil
  tv.structure.loaded = false
  M.load_structure(tv)
end

function M.set_page(tv, offset)
  tv.data.offset = offset
  M.load_data(tv)
end

function M.apply_filter(tv, text)
  tv.data.filter = U.trim(text or tv.data.draft)
  tv.data.draft = tv.data.filter
  tv.data.offset = 0
  tv.grid.sel = 1
  M.load_data(tv)
end

function M.set_order(tv, column)
  tv.data.order = column
  tv.data.offset = 0
  M.load_data(tv)
end

function M.toggle_desc(tv)
  tv.data.desc = not tv.data.desc
  tv.data.offset = 0
  if tv.data.order ~= "" then
    M.load_data(tv)
  else
    S.redraw()
  end
end

return M
end

-- src/features/table/structure.lua ------------------------------------------
__modules["features.table.structure"] = function()
local ttt = require("ttt")
local U = require("core.util")
local UI = require("components")
local Store = require("features.table.store")

local M = {}

local ORIGINS = { c = "index", u = "unique constraint", pk = "primary key" }
local HIDDEN = { ["1"] = "hidden", ["2"] = "generated (virtual)", ["3"] = "generated (stored)" }

local function yes(v)
  return tonumber(v) and tonumber(v) ~= 0 and "yes" or ""
end

local function column_rows(st)
  local rows = {}
  for i, c in ipairs(st.columns or {}) do
    local pk = tonumber(c.pk) or 0
    rows[i] = {
      tostring(i),
      c.name or "",
      c.type or "",
      yes(c.not_null),
      c.dflt_value or "",
      pk > 0 and tostring(pk) or "",
      HIDDEN[tostring(c.hidden)] or "",
    }
  end
  return rows
end

local COLUMN_COLS = {
  { label = "#", width = 3, align = "right" },
  { label = "Name" },
  { label = "Type", width = 14 },
  { label = "Not null", width = 8 },
  { label = "Default" },
  { label = "PK", width = 3, align = "right" },
  { label = "Notes", width = 20 },
}

local function index_rows(st)
  local rows = {}
  for i, x in ipairs(st.indexes or {}) do
    rows[i] = {
      x.name or "",
      x.cols or "",
      yes(x.uniq),
      ORIGINS[x.origin] or x.origin or "",
      yes(x.partial),
    }
  end
  return rows
end

local INDEX_COLS = {
  { label = "Name" },
  { label = "Columns" },
  { label = "Unique", width = 6 },
  { label = "Origin", width = 17 },
  { label = "Partial", width = 7 },
}

local function fk_rows(st)
  local rows = {}
  for i, fk in ipairs(st.fks or {}) do
    local target = fk.ref .. (#fk.dst > 0 and ("(" .. table.concat(fk.dst, ", ") .. ")") or "")
    rows[i] = { table.concat(fk.src, ", "), target, fk.on_update or "", fk.on_delete or "" }
  end
  return rows
end

local FK_COLS = {
  { label = "Columns" },
  { label = "References" },
  { label = "On update", width = 11 },
  { label = "On delete", width = 11 },
}

local function trigger_rows(st)
  local rows = {}
  for i, t in ipairs(st.triggers or {}) do
    rows[i] = { t.name or "", U.clip(U.one_line(t.sql or ""), 120) }
  end
  return rows
end

local TRIGGER_COLS = { { label = "Name", width = 28 }, { label = "Definition" } }

local function table_body(cols, rows, empty, b)
  b:table({ inset = 1, columns = cols, rows = rows, empty = empty })
end

local function section(p, title, cols, rows, empty)
  local height = math.max(#rows, 1) + 5
  UI.frame(p, title .. " (" .. #rows .. ")", U.bind(table_body, cols, rows, empty), { height = height, margin_top = 1 })
end

local function sql_text(tv)
  local st = tv.structure
  local parts = { st.sql ~= "" and (table.concat(U.format_create(st.sql), "\n") .. ";") or "" }
  for _, x in ipairs(st.indexes or {}) do
    if x.sql then
      parts[#parts + 1] = x.sql .. ";"
    end
  end
  for _, t in ipairs(st.triggers or {}) do
    if t.sql then
      parts[#parts + 1] = t.sql .. ";"
    end
  end
  return table.concat(parts, "\n\n")
end

local function open_sql(tv)
  ttt.open_readonly(tv.name .. ".sql", U.lines(sql_text(tv)), tv.name .. ".sql")
end

local function sql_body(tv, width, b)
  for _, line in ipairs(U.format_create(tv.structure.sql)) do
    for _, part in ipairs(U.wrap(line, math.max(width - 6, 20))) do
      b:label({ text = part == "" and " " or part, style = "code", padding_left = 1 })
    end
  end
end

local function sql_actions(tv, h)
  h:label({ text = "" })
  h:button({ label = "Open as SQL", on_click = U.bind(open_sql, tv) })
end

local function body(tv, width, p)
  local st = tv.structure
  section(p, "Columns", COLUMN_COLS, column_rows(st), "No columns")
  if tv.kind ~= "view" then
    section(p, "Indexes", INDEX_COLS, index_rows(st), "No indexes")
    section(p, "Foreign keys", FK_COLS, fk_rows(st), "No foreign keys")
  end
  if #(st.triggers or {}) > 0 then
    section(p, "Triggers", TRIGGER_COLS, trigger_rows(st), "")
  end
  UI.frame(p, "CREATE statement", U.bind(sql_body, tv, width), { margin_top = 1 })
  p:hstack({ height = 1, margin_top = 1, render = U.bind(sql_actions, tv) })
end

function M.render(p, tv)
  Store.ensure_structure(tv)
  local st = tv.structure
  if not st.loaded then
    p:label({ text = "Loading structure…", style = "muted", margin_top = 1, padding_left = 1 })
    return
  end
  if st.err then
    p:label({ text = "✕ " .. U.one_line(st.err), style = "danger", margin_top = 1, padding_left = 1 })
  end
  p:scrollview({ render = U.bind(body, tv, (p:size())) })
end

return M
end

-- src/main.lua --------------------------------------------------------------
__modules["main"] = function()
local ttt = require("ttt")
local S = require("core.state")
local Db = require("core.db")
local Router = require("app.router")
local Sidebar = require("app.sidebar")
local Open = require("app.open")
local Attach = require("app.attach")
local Settings = require("app.settings")
local Query = require("features.query")
local Overview = require("features.overview")

local function new_query()
  if not Query.open(S.current) then
    Open.dialog()
  end
end

local function refresh()
  if S.current then
    Db.load(S.current)
  end
end

local function close_database()
  local db = S.current
  if db then
    Router.close_db(db.path)
    Db.close(db)
  end
end

local function show_panel()
  ttt.focus_panel("sidebar")
end

local actions = {
  open = Open.dialog,
  query = new_query,
  attach = Attach.dialog,
  detach = Attach.detach_current,
  refresh = refresh,
  close = close_database,
  settings = Settings.dialog,
}

local function on_action(cmd)
  local run = actions[cmd]
  if run then
    run()
  end
end

ttt.register({
  sidebar = {
    title = "SQLite",
    render = Sidebar.render,
    actions = {
      { label = "Open Database…", command = "open" },
      { label = "New Query", command = "query" },
      { separator = true },
      { label = "Attach Database…", command = "attach" },
      { label = "Detach Schema", command = "detach" },
      { label = "Refresh", command = "refresh" },
      { label = "Close Database", command = "close" },
      { separator = true },
      { label = "Settings…", command = "settings" },
    },
    on_action = on_action,
  },
  commands = {
    { id = "sqlite.openDatabase", title = "SQLite: Open Database…", handler = Open.dialog },
    { id = "sqlite.newQuery", title = "SQLite: New Query", handler = new_query },
    { id = "sqlite.attachDatabase", title = "SQLite: Attach Database…", handler = Attach.dialog },
    { id = "sqlite.detachSchema", title = "SQLite: Detach Schema", handler = Attach.detach_current },
    { id = "sqlite.refresh", title = "SQLite: Refresh", handler = refresh },
    { id = "sqlite.closeDatabase", title = "SQLite: Close Database", handler = close_database },
    { id = "sqlite.showPanel", title = "SQLite: Show Panel", handler = show_panel },
    { id = "sqlite.settings", title = "SQLite: Settings…", handler = Settings.dialog },
  },
  file_handlers = {
    {
      id = "sqlite",
      title = "SQLite",
      extensions = { "sqlite", "sqlite3", "db" },
      magic = "SQLite format 3\0",
      open = Overview.open_file,
    },
  },
})
end

require("main")
